import {
	type HeatMapDatum,
	type HeatMapSvgProps,
	ResponsiveHeatMap as Heatmap,
} from "@harbor-charts/heatmap";
import {
	Component,
	Element,
	Host,
	Listen,
	Method,
	Prop,
	h,
} from "@stencil/core";
import * as React from "react";
import { createRoot } from "react-dom/client";
import retargetEvents from "react-shadow-dom-retarget-events";

import { heatmap } from "@harbor/chart-config/heatmap";

const { getHeatmapBaseConfig, getHeatmapCategoricalConfig } = heatmap;

import merge from "deepmerge";
import { browserDownloadCsv } from "../chart-board/board-util";
import {
	noopChartTooltip,
	omitChartConfigKeys,
} from "../chart-board/chart-config-util";
import {
	type ChartPopoverOptions,
	isChartPopoverSelfManaged,
	resolveChartPopoverOptions,
} from "../chart-board/popover-options";
import type { HbrPopover } from "../popover/popover";
import {
	convertHeatmapDataToCSV,
	heatmapItemToggleTooltip,
	hideHeatmapPopover,
	showHeatmapAxisPopover,
	showHeatmapLegendPopover,
} from "./chart-util";

type HbrTooltipFunctions = {
	itemTooltip?: (data, event) => string | object | false;
	legendTooltip?: (data, event, h) => string | object | false;
};

type HeatmapPatternConfig = {
	type?: "pattern" | "halftone-point" | "halftone-line";
	color?: string;
	baseSize?: number;
	cellCornerPointMultipliers?: number[];
	legendPointMultipliers?: number[];
	cellPointMultipliers?: number[];
	legendLineMultipliers?: number[];
	cellLineMultipliers?: number[];
};

type HeatmapProps = HeatMapSvgProps<HeatMapDatum, Record<string, unknown>>;
type HeatmapAxisProps = NonNullable<HeatmapProps["axisTop"]>;
type HeatmapLegendProps = NonNullable<HeatmapProps["legends"]>[number];
type AxisInteractionConfig = HeatmapAxisProps & {
	onMouseEnter?: (data, event, tick) => void;
	onMouseMove?: (data, event, tick) => void;
	onMouseLeave?: (data, event, tick) => void;
	onFocus?: (data, event, tick) => void;
	onBlur?: (data, event, tick) => void;
	tooltip?: (data, event) => string | object | false;
	popoverOptions?: ChartPopoverOptions;
};

type LegendInteractionConfig = HeatmapLegendProps & {
	onMouseEnter?: (data, event) => void;
	onMouseMove?: (data, event) => void;
	onMouseLeave?: (data, event) => void;
	onFocus?: (data, event) => void;
	onBlur?: (data, event) => void;
	popoverOptions?: ChartPopoverOptions;
};

type BaseHeatmapConfig = Omit<
	Partial<HeatmapProps>,
	"axisTop" | "axisRight" | "axisBottom" | "axisLeft" | "legends" | "tooltip"
> &
	HbrTooltipFunctions & {
		axisLabelFontSize?: number;
		labelStyle?: React.CSSProperties;
		pattern?: boolean | HeatmapPatternConfig;
		axisTop?: AxisInteractionConfig | null;
		axisRight?: AxisInteractionConfig | null;
		axisBottom?: AxisInteractionConfig | null;
		axisLeft?: AxisInteractionConfig | null;
		legends?: LegendInteractionConfig[];
	};

type ConfigWithNivoTooltip = BaseHeatmapConfig & { tooltip?: unknown };

type CategoricalRuntimeConfig = BaseHeatmapConfig &
	HbrTooltipFunctions & {
		legendContainerWidth?: number;
		legendContainerHeight?: number;
	};

type HeatmapAxis = "axisTop" | "axisRight" | "axisBottom" | "axisLeft";

const AXIS_KEYS: HeatmapAxis[] = [
	"axisTop",
	"axisRight",
	"axisBottom",
	"axisLeft",
];

const AXIS_DEFAULT_PLACEMENTS: Record<HeatmapAxis, HbrPopover["placement"]> = {
	axisTop: "top",
	axisRight: "right",
	axisBottom: "bottom",
	axisLeft: "left",
};

const getTickValueKey = (value: unknown) =>
	value instanceof Date
		? `date:${value.getTime()}`
		: `${typeof value}:${String(value)}`;

const dedupeTickValues = (tickValues: unknown[]) => {
	const seen = new Set<string>();
	return tickValues.filter((value) => {
		const key = getTickValueKey(value);
		if (seen.has(key)) {
			return false;
		}
		seen.add(key);
		return true;
	});
};

const normalizeAxisTickValues = <T extends BaseHeatmapConfig>(config: T): T => {
	let hasChanges = false;
	const normalizedConfig = { ...config } as T;

	AXIS_KEYS.forEach((axisKey) => {
		const axisConfig = normalizedConfig[axisKey] as
			| (Partial<Record<string, unknown>> & { tickValues?: unknown[] })
			| undefined;

		if (!axisConfig || !Array.isArray(axisConfig.tickValues)) {
			return;
		}

		const normalizedTickValues = dedupeTickValues(axisConfig.tickValues);
		if (normalizedTickValues.length === axisConfig.tickValues.length) {
			return;
		}

		hasChanges = true;
		normalizedConfig[axisKey] = {
			...axisConfig,
			tickValues: normalizedTickValues,
		} as T[typeof axisKey];
	});

	return hasChanges ? normalizedConfig : config;
};

/**
 * @since 1.2.17
 * @status stable
 * @part chart - The chart element
 * @part header - The header element
 * @part popover-body - The popover body element, check hbr-popover for more details
 * @part popover-popup - The popover popup element,  check hbr-popover for more details
 * @part popover-arrow - The popover arrow element,  check hbr-popover for more details
 *
 * @slot header - Slot for header
 * @slot header-title - Slot for header title
 * @slot header-action - Slot for header action
 * @slot footer - Slot for footer
 * @slot loading-state - Slot for loading state
 * @slot empty-state - Slot for empty state
 * @slot content - Slot for popover content
 */
@Component({
	tag: "hbr-heatmap-chart",
	styleUrl: "style.scss",
	shadow: true,
})
export class HbrHeatmapChart {
	chartRef: HTMLElement;
	tooltipRef: HTMLHbrPopoverElement;
	boardRef: HTMLHbrChartBoardElement;
	observer: MutationObserver = null;

	/** Chart configuration object. Refer to https://nivo.rocks/heatmap */
	@Prop({ mutable: true }) config: BaseHeatmapConfig = { data: [] };
	/** Chart width */
	@Prop() width = "100%";
	/** Chart height */
	@Prop() height = "360px";

	/** Chart loading flag */
	@Prop() loading = false;

	/** New Magnetic UX chart type */
	@Prop({ reflect: true }) categorical = false;

	/** Final config before rendering, param1 is the final config, your customization should be done here */
	@Prop() modifyHbrConfig: (
		config: BaseHeatmapConfig,
		createElement: typeof React.createElement,
		util: typeof heatmap,
	) => ConfigWithNivoTooltip;

	/** Default popover props. Set `selfManaged` to let a categorical heatmap popover manage its own open and close behavior. */
	@Prop() popoverOptions: ChartPopoverOptions;

	@Element() private el: HTMLHbrHeatmapChartElement;

	/** Public method for download data, use customFunc to create your own way to download data, such as pdf */
	@Method()
	async download(filename = "Export.csv", customFunc?: (data) => void) {
		if (customFunc) {
			customFunc(this.config.data);
		} else {
			browserDownloadCsv(convertHeatmapDataToCSV(this.config.data), filename);
		}
	}

	/** Public method to get popover reference, client can use this to control magnetic UX popover externally */
	@Method()
	async getPopoverRef() {
		return this.tooltipRef;
	}

	// saved react object after it is rendered
	// this is for update since react will complain if creating root again during update
	private contextRoot = null;
	private activePopoverSelfManaged: boolean | null = null;
	private warnedAboutNivoTooltip = false;

	private getPopoverOptions(
		defaultPlacement: HbrPopover["placement"] = "top",
		override?: ChartPopoverOptions,
	): Partial<HbrPopover> {
		return resolveChartPopoverOptions(
			{
				distance: 10,
				variant: "chart",
				placement: defaultPlacement,
			},
			this.popoverOptions,
			this.categorical,
			override,
		);
	}

	private getActivePopoverOptions(
		defaultPlacement: HbrPopover["placement"] = "top",
		override?: ChartPopoverOptions,
	): Partial<HbrPopover> {
		this.activePopoverSelfManaged = this.isPopoverSelfManaged(override);
		return this.getPopoverOptions(defaultPlacement, override);
	}

	private isPopoverSelfManaged(override?: ChartPopoverOptions) {
		return isChartPopoverSelfManaged(
			this.categorical,
			this.popoverOptions,
			override,
		);
	}

	private getAxisPopoverOptions(
		axis: HeatmapAxis,
		override?: ChartPopoverOptions,
	): Partial<HbrPopover> {
		return this.getActivePopoverOptions(
			AXIS_DEFAULT_PLACEMENTS[axis],
			override,
		);
	}

	private getCategoricalAxisConfig(
		axis: HeatmapAxis,
		axisConfig?: AxisInteractionConfig,
	): AxisInteractionConfig {
		const dimension = axis === "axisTop" || axis === "axisBottom" ? "x" : "y";
		const showPopover = (data, event, tick) => {
			showHeatmapAxisPopover(
				this.tooltipRef,
				event,
				data,
				dimension,
				tick?.format ? tick.format(tick.value) : tick?.value,
				this.getAxisPopoverOptions(axis, axisConfig?.popoverOptions),
				axisConfig?.tooltip,
			);
		};

		return {
			...axisConfig,
			onMouseEnter: (data, event, tick) => {
				showPopover(data, event, tick);
				axisConfig?.onMouseEnter?.(data, event, tick);
			},
			onMouseMove: (data, event, tick) => {
				showPopover(data, event, tick);
				axisConfig?.onMouseMove?.(data, event, tick);
			},
			onMouseLeave: (data, event, tick) => {
				if (!this.isPopoverSelfManaged(axisConfig?.popoverOptions)) {
					hideHeatmapPopover(this.tooltipRef);
				}
				axisConfig?.onMouseLeave?.(data, event, tick);
			},
			onFocus: (data, event, tick) => {
				showPopover(data, event as unknown as MouseEvent, tick);
				axisConfig?.onFocus?.(data, event, tick);
			},
			onBlur: (data, event, tick) => {
				this.activePopoverSelfManaged = false;
				hideHeatmapPopover(this.tooltipRef);
				axisConfig?.onBlur?.(data, event, tick);
			},
		};
	}

	componentDidLoad() {
		this.renderChart();
		retargetEvents(this.el.shadowRoot);
	}

	componentShouldUpdate() {
		return this.renderChart();
	}

	@Listen("mouseout", { passive: true })
	handleHoverOut() {
		if (this.activePopoverSelfManaged ?? this.isPopoverSelfManaged()) {
			return;
		}

		heatmapItemToggleTooltip(
			this.tooltipRef,
			null,
			null,
			undefined,
			this.config.itemTooltip,
		);
	}

	disconnectedCallback() {
		if (this.observer) {
			this.observer.disconnect();
			this.observer = null;
		}
	}

	renderChart = async () => {
		const configWithNivoTooltip = this.config as BaseHeatmapConfig & {
			tooltip?: unknown;
		};
		if (
			!this.warnedAboutNivoTooltip &&
			configWithNivoTooltip.tooltip !== undefined
		) {
			console.warn(
				"hbr-heatmap-chart: config.tooltip is not supported. Use itemTooltip or legendTooltip instead.",
			);
			this.warnedAboutNivoTooltip = true;
		}
		const publicConfig = omitChartConfigKeys(configWithNivoTooltip, [
			"tooltip",
		]) as BaseHeatmapConfig;
		const configuredMargin = this.categorical
			? {
					top:
						typeof this.config?.margin?.top === "number"
							? this.config.margin.top
							: 40,
					right:
						typeof this.config?.margin?.right === "number"
							? this.config.margin.right
							: 60,
					bottom:
						typeof this.config?.margin?.bottom === "number"
							? this.config.margin.bottom
							: 90,
					left:
						typeof this.config?.margin?.left === "number"
							? this.config.margin.left
							: 60,
			  }
			: null;
		const chartRect = this.el?.getBoundingClientRect?.();
		const legendContainerWidth =
			this.categorical && configuredMargin
				? Math.max(
						(chartRect?.width || this.chartRef?.clientWidth || 0) -
							configuredMargin.left -
							configuredMargin.right,
						0,
				  )
				: undefined;
		const legendContainerHeight =
			this.categorical && configuredMargin
				? Math.max(
						(chartRect?.height || this.chartRef?.clientHeight || 0) -
							configuredMargin.top -
							configuredMargin.bottom,
						0,
				  )
				: undefined;
		const axisTopConfig = publicConfig.axisTop as
			| AxisInteractionConfig
			| undefined;
		const axisRightConfig = publicConfig.axisRight as
			| AxisInteractionConfig
			| undefined;
		const axisBottomConfig = publicConfig.axisBottom as
			| AxisInteractionConfig
			| undefined;
		const axisLeftConfig = publicConfig.axisLeft as
			| AxisInteractionConfig
			| undefined;
		const legendConfig =
			Array.isArray(publicConfig.legends) && publicConfig.legends.length
				? (publicConfig.legends[0] as LegendInteractionConfig | undefined)
				: undefined;
		const configWithCategoricalAxisHandlers:
			| CategoricalRuntimeConfig
			| BaseHeatmapConfig = this.categorical
			? {
					...publicConfig,
					legendContainerWidth,
					legendContainerHeight,
					...(axisTopConfig && {
						axisTop: this.getCategoricalAxisConfig("axisTop", axisTopConfig),
					}),
					...(axisRightConfig && {
						axisRight: this.getCategoricalAxisConfig(
							"axisRight",
							axisRightConfig,
						),
					}),
					axisBottom: this.getCategoricalAxisConfig(
						"axisBottom",
						axisBottomConfig,
					),
					axisLeft: this.getCategoricalAxisConfig("axisLeft", axisLeftConfig),
					legends: Array.isArray(publicConfig.legends)
						? publicConfig.legends.map((legend, index) =>
								index === 0
									? {
											...legend,
											onMouseEnter: (data, event) => {
												showHeatmapLegendPopover(
													this.tooltipRef,
													event,
													data,
													this.getActivePopoverOptions(
														"top",
														legendConfig?.popoverOptions,
													),
													this.config.legendTooltip,
													true,
												);
												legendConfig?.onMouseEnter?.(data, event);
											},
											onMouseMove: (data, event) => {
												showHeatmapLegendPopover(
													this.tooltipRef,
													event,
													data,
													this.getActivePopoverOptions(
														"top",
														legendConfig?.popoverOptions,
													),
													this.config.legendTooltip,
													true,
												);
												legendConfig?.onMouseMove?.(data, event);
											},
											onMouseLeave: (data, event) => {
												if (
													!this.isPopoverSelfManaged(
														legendConfig?.popoverOptions,
													)
												) {
													hideHeatmapPopover(this.tooltipRef);
												}
												legendConfig?.onMouseLeave?.(data, event);
											},
											onFocus: (data, event) => {
												showHeatmapLegendPopover(
													this.tooltipRef,
													event as unknown as MouseEvent,
													data,
													this.getActivePopoverOptions(
														"top",
														legendConfig?.popoverOptions,
													),
													this.config.legendTooltip,
													true,
												);
												legendConfig?.onFocus?.(data, event);
											},
											onBlur: (data, event) => {
												this.activePopoverSelfManaged = false;
												hideHeatmapPopover(this.tooltipRef);
												legendConfig?.onBlur?.(data, event);
											},
									  }
									: legend,
						  )
						: publicConfig.legends,
			  }
			: publicConfig;

		const baseConfig = this.categorical
			? getHeatmapCategoricalConfig(
					configWithCategoricalAxisHandlers as never,
					{
						itemsEventHandlers: {
							onMouseEnter: (node, event) => {
								heatmapItemToggleTooltip(
									this.tooltipRef,
									event,
									node,
									this.getActivePopoverOptions(),
									this.config.itemTooltip,
									true,
								);
							},
							onMouseLeave: (node, _event) => {
								if (!this.isPopoverSelfManaged()) {
									heatmapItemToggleTooltip(
										this.tooltipRef,
										null,
										node,
										this.getActivePopoverOptions(),
										this.config.itemTooltip,
										true,
									);
								}
							},
							onFocus: (node, event) => {
								heatmapItemToggleTooltip(
									this.tooltipRef,
									event,
									node,
									this.getActivePopoverOptions(),
									this.config.itemTooltip,
									true,
								);
							},
						},
					},
			  )
			: getHeatmapBaseConfig(publicConfig, {
					itemsEventHandlers: {
						onMouseEnter: (node, event) => {
							heatmapItemToggleTooltip(
								this.tooltipRef,
								event,
								node,
								this.getActivePopoverOptions(),
								this.config.itemTooltip,
							);
						},
						onMouseLeave: (node, _event) => {
							heatmapItemToggleTooltip(
								this.tooltipRef,
								null,
								node,
								this.getActivePopoverOptions(),
								this.config.itemTooltip,
							);
						},
						onFocus: (node, event) => {
							heatmapItemToggleTooltip(
								this.tooltipRef,
								event,
								node,
								this.getActivePopoverOptions(),
								this.config.itemTooltip,
							);
						},
					},
			  });

		const existingEventHandlers = {
			onMouseEnter: baseConfig.onMouseEnter,
			onMouseLeave: baseConfig.onMouseLeave,
			onMouseMove: baseConfig.onMouseMove,
			onClick: baseConfig.onClick,
			onblur: baseConfig.onBlur,
			onFocus: baseConfig.onFocus,
		};

		let fullConfig = merge<BaseHeatmapConfig>(
			baseConfig as unknown as BaseHeatmapConfig,
			publicConfig,
			{
				customMerge: (key) => {
					if (key === "legends") {
						return (a, b) => {
							const ret =
								a.length > b.length
									? a.map((r, i) => ({ ...r, ...b[i] }))
									: b.map((r, i) => ({ ...a[i], ...r }));
							return ret;
						};
					}
				},
			},
		);

		fullConfig = {
			...fullConfig,
			...existingEventHandlers,
		} as unknown as BaseHeatmapConfig;
		fullConfig = normalizeAxisTickValues(fullConfig);
		fullConfig = omitChartConfigKeys(fullConfig, [
			"tooltip",
		]) as BaseHeatmapConfig;

		if (this.modifyHbrConfig) {
			fullConfig = this.modifyHbrConfig(
				fullConfig,
				React.createElement,
				heatmap,
			);
		}
		fullConfig = {
			...fullConfig,
			tooltip:
				(fullConfig as ConfigWithNivoTooltip).tooltip ?? noopChartTooltip,
		} as BaseHeatmapConfig & { tooltip: typeof noopChartTooltip };
		const patternConfig =
			fullConfig.pattern && typeof fullConfig.pattern === "object"
				? fullConfig.pattern
				: {};
		const heatmapRenderKey = `categorical:${
			this.categorical ? "1" : "0"
		}:pattern:${fullConfig.pattern ? "1" : "0"}:pattern-type:${
			patternConfig.type ?? "pattern"
		}:pattern-color:${patternConfig.color ?? ""}:pattern-base-size:${
			patternConfig.baseSize ?? ""
		}:halftone-cell-corners:${JSON.stringify(
			patternConfig.cellCornerPointMultipliers ?? [],
		)}:halftone-legend-multipliers:${JSON.stringify(
			patternConfig.legendPointMultipliers ?? [],
		)}:halftone-cell-multipliers:${JSON.stringify(
			patternConfig.cellPointMultipliers ?? [],
		)}:halftone-legend-line-multipliers:${JSON.stringify(
			patternConfig.legendLineMultipliers ?? [],
		)}:halftone-cell-line-multipliers:${JSON.stringify(
			patternConfig.cellLineMultipliers ?? [],
		)}`;

		if (!this.chartRef?.innerHTML?.length) {
			const newRoot = createRoot(this.chartRef);
			await newRoot.render(
				React.createElement(
					Heatmap,
					{
						key: heatmapRenderKey,
						...(fullConfig as HeatMapSvgProps<
							HeatMapDatum,
							Record<string, unknown>
						>),
					},
					null,
				),
			);
			this.contextRoot = newRoot;
		} else {
			await this.contextRoot.render(
				React.createElement(
					Heatmap,
					{
						key: heatmapRenderKey,
						...(fullConfig as HeatMapSvgProps<
							HeatMapDatum,
							Record<string, unknown>
						>),
					},
					null,
				),
			);
		}

		if (this.boardRef.setChartConfig) {
			this.boardRef.setChartConfig(fullConfig);
		}
	};

	render() {
		this.el.style.width = this.width;
		this.el.style.height = this.height;
		const popoverOptions = this.getPopoverOptions();

		return (
			<Host>
				<hbr-chart-board
					type="bar"
					ref={(el) => {
						this.boardRef = el;
					}}
					isLoading={this.loading}
					isEmpty={!this.config.data?.length}
					style={{ width: this.width, height: this.height }}
					exportparts="empty-state-illustration, empty-state-image, loading-state-illustration, loading-state-image"
				>
					<hbr-popover
						{...popoverOptions}
						ref={(el) => {
							this.tooltipRef = el;
						}}
						part="popover"
						exportparts="base__popup:popover-popup, base__arrow:popover-arrow, body:popover-body"
						anchor=""
					>
						<div slot="content" />
					</hbr-popover>
					<div slot="header" part="header" class="chart-heatmap__header">
						<slot name="header">
							<div>
								<slot name="header-title" />
							</div>
							<div>
								<slot name="header-action" />
							</div>
						</slot>
					</div>
					<div
						ref={(el) => {
							this.chartRef = el;
						}}
						class="--hbr-heatmap --heatmap-chart"
						part="chart"
					/>
					<slot name="footer" />
					<slot slot="loading-state" name="loading-state" />
					<slot slot="empty-state" name="empty-state" />
				</hbr-chart-board>
			</Host>
		);
	}
}
