import { hideChartPopover, showChartPopover } from "../chart-board/board-util";
import type { HbrPopover } from "../popover/popover";

function generateHeatmapDefaultPopover(node, categorical = false) {
	const popoverClass = categorical
		? " chart-heatmap__popover--categorical"
		: "";
	const cellLabelClass = categorical
		? ' class="chart-heatmap__popover-cell-label"'
		: "";
	const cellValueClass = categorical
		? ' class="chart-heatmap__popover-cell-value"'
		: "";
	let color = node.fill || node.data?.color || node.color;
	if (node.data.y === undefined || node.data.y === null) {
		color = `url(#${node.noDataPattern?.getAttribute("id")})`;
	}
	return `
	    <div class="chart-heatmap__popover${popoverClass}">
      <div${cellLabelClass}>
        <svg width="16" height="16">
          ${node.patternDef ? `<defs>${node.patternDef}</defs>` : ""}
          <rect width="16" height="16" fill="${color}"></rect>
        </svg>
        ${node.serieId} - ${node.data.x}
      </div>
      <div${cellValueClass}>
        ${
					node.data.y === undefined || node.data.y === null
						? "No data"
						: node.data.y
				}
      </div>
    </div>
	`;
}

function getPatternIdFromFill(fill?: string | null) {
	const match = fill?.match(/^url\(#(.+)\)$/);
	return match?.[1];
}

function getPatternDefFromFill(event: Event, fill?: string | null) {
	const patternId = getPatternIdFromFill(fill);
	const svgRoot = (event.target as HTMLElement)?.closest?.("svg");
	if (!patternId || !svgRoot) {
		return undefined;
	}

	return svgRoot.querySelector(`#${patternId}`)?.outerHTML;
}

function getEventTargetSvgFill(event: Event) {
	const target = event.target as SVGElement | null;
	return target?.getAttribute?.("fill") || undefined;
}

function getHeatmapPopoverPatternPayload(payload, event: Event) {
	const fill = payload?.fill || getEventTargetSvgFill(event);

	if (!fill) {
		return payload;
	}

	return {
		...payload,
		fill,
		patternDef: getPatternDefFromFill(event, fill),
	};
}

function getHeatmapAxisItemColor(node, event) {
	if (node?.color) {
		return node.color;
	}

	const svgRoot = (event.target as HTMLElement)?.closest?.("svg");
	if (!svgRoot) {
		return "#5B66E6";
	}

	const selector = `[series='${node.serieId}'][xid='${node.x}']`;
	return (
		svgRoot.querySelector(selector)?.getAttribute("fill") ||
		svgRoot.querySelector(selector)?.getAttribute("stroke") ||
		"#5B66E6"
	);
}

function getHeatmapAxisPopoverPayload(axis, label, data, event) {
	return {
		axis,
		label,
		items: data.map((node) => ({
			...node,
			color: getHeatmapAxisItemColor(node, event),
		})),
	};
}

function generateHeatmapAxisPopover(payload) {
	const rows = payload.items
		.map((item) => {
			const itemLabel = payload.axis === "x" ? item.serieId : item.x;

			return `
				<div class="chart-heatmap__popover">
					<div>
						<svg width="16" height="16">
							<rect width="16" height="16" rx="2" fill="${item.color}"></rect>
						</svg>
						${itemLabel}
					</div>
					<div>
						${item?.y ?? ""}
					</div>
				</div>
			`;
		})
		.join("");

	return `
		<div style="display:grid;gap:10px">
			<div style="font-weight:600;">${payload.label}</div>
			${rows}
		</div>
	`;
}

function generateHeatmapLegendPopover(section, categorical = false) {
	const popoverClass = categorical
		? " chart-heatmap__popover--categorical"
		: "";
	const legendPopoverClass = categorical
		? ' class="chart-heatmap__legend-popover--categorical"'
		: "";
	const legendTitleClass = categorical
		? ' class="chart-heatmap__legend-title"'
		: "";
	const legendLabelClass = categorical
		? ' class="chart-heatmap__legend-label"'
		: "";
	const legendValueClass = categorical
		? ' class="chart-heatmap__legend-value"'
		: "";
	const swatchFill = section.fill || section.color;
	const swatchDef = section.patternDef
		? `<defs>${section.patternDef}</defs>`
		: "";

	if (Array.isArray(section?.groups)) {
		if (!section.groups.length) {
			return `
				<div${legendPopoverClass} style="display:grid;gap:10px;padding:2px 0;">
					<div${legendTitleClass}>Title</div>
					<div style="font-size:14px;line-height:20px;color:#4b5563;">No matching cells</div>
				</div>
			`;
		}

		const rows = section.groups
			.map(
				(group) => `
					<div style="display:grid;gap:10px;">
						<div style="display:flex;align-items:center;gap:10px;">
							<svg width="16" height="16" style="flex:none;">
								${swatchDef}
								<rect width="16" height="16" rx="2" ry="2" fill="${swatchFill}"></rect>
							</svg>
							<div${legendValueClass}>${group.id}</div>
						</div>
						<div style="display:grid;gap:8px;padding-left:26px;">
							${group.matches
								.map(
									(item) => `
										<div style="display:flex;align-items:center;justify-content:space-between;gap:24px;">
											<div${legendLabelClass}>${item.x}</div>
											<div${legendValueClass}>${item.y}</div>
										</div>
									`,
								)
								.join("")}
						</div>
					</div>
				`,
			)
			.join("");

		return `
			<div${legendPopoverClass} style="display:grid;gap:16px;padding:2px 0;">
				<div${legendTitleClass}>Title</div>
				${rows}
			</div>
		`;
	}

	return `
		<div class="chart-heatmap__popover${popoverClass}">
			<div>
				<svg width="16" height="16">
					${swatchDef}
					<rect width="16" height="16" fill="${swatchFill}"></rect>
				</svg>
				${section.label}
			</div>
		</div>
	`;
}

function toggleHeatmapLegendHoverClass(event: Event, section?) {
	const svgRoot = (event.target as HTMLElement)?.closest?.("svg");
	if (!svgRoot) {
		return;
	}

	const heatmapNodes = [
		...svgRoot.querySelectorAll<SVGGElement>(".--heatmap-cell"),
	];

	if (!section || !Array.isArray(section.groups)) {
		heatmapNodes.forEach((node) => {
			node.classList?.remove(
				"--heatmap-cell-dehighlight",
				"--heatmap-cell-associated",
				"--heatmap-cell-highlight",
			);
		});
		return;
	}

	const matchedKeys = new Set(
		section.groups.flatMap((group) =>
			group.matches.map((item) => `${group.id}::${String(item.x)}`),
		),
	);

	heatmapNodes.forEach((node) => {
		const cell = node.firstChild as HTMLElement | null;
		const key = `${cell?.getAttribute("series") ?? ""}::${
			cell?.getAttribute("xid") ?? ""
		}`;

		if (matchedKeys.has(key)) {
			node.classList?.add("--heatmap-cell-highlight");
			node.classList?.remove(
				"--heatmap-cell-associated",
				"--heatmap-cell-dehighlight",
			);
		} else {
			node.classList?.add("--heatmap-cell-dehighlight");
			node.classList?.remove(
				"--heatmap-cell-associated",
				"--heatmap-cell-highlight",
			);
		}
	});
}

function applyPopoverOptions(
	tooltipRef: HTMLHbrPopoverElement,
	popoverOptions?: Partial<HbrPopover>,
) {
	if (!tooltipRef || !popoverOptions) {
		return;
	}

	Object.entries(popoverOptions).forEach(([key, value]) => {
		if (value !== undefined) {
			Reflect.set(tooltipRef, key, value);
		}
	});
}

const heatmapItemToggleTooltip = (
	tooltipRef,
	event?,
	node?,
	popoverOptions?,
	customTooltipFunc?,
	categorical = false,
) => {
	if (event) {
		applyPopoverOptions(tooltipRef, popoverOptions);
		showChartPopover(
			tooltipRef,
			getHeatmapPopoverPatternPayload(node, event),
			event,
			customTooltipFunc,
			(node) => generateHeatmapDefaultPopover(node, categorical),
		);
	} else {
		hideChartPopover(tooltipRef);
	}
};

const showHeatmapAxisPopover = (
	tooltipRef,
	event,
	data,
	axis,
	label,
	popoverOptions?,
	customTooltipFunc?,
) => {
	applyPopoverOptions(tooltipRef, popoverOptions);
	showChartPopover(
		tooltipRef,
		getHeatmapAxisPopoverPayload(axis, label, data, event),
		event,
		customTooltipFunc,
		generateHeatmapAxisPopover,
	);
};

const hideHeatmapPopover = (tooltipRef) => {
	hideChartPopover(tooltipRef);
};

const showHeatmapLegendPopover = (
	tooltipRef,
	event,
	data,
	popoverOptions?,
	customTooltipFunc?,
	categorical = false,
) => {
	applyPopoverOptions(tooltipRef, popoverOptions);
	showChartPopover(
		tooltipRef,
		getHeatmapPopoverPatternPayload(data, event),
		event,
		customTooltipFunc,
		(section) => generateHeatmapLegendPopover(section, categorical),
	);
};

const convertHeatmapDataToCSV = (arr) => {
	const csv = [];
	const headers = arr[0].data.map((item) => item.x);

	// Get the headers from the first object
	csv.push(` ,${headers.join(",")}`);

	// Iterate over each object and convert it to a CSV row
	arr.forEach((obj) => {
		const row = [];
		headers.forEach((header) => {
			const target = obj.data.find((r) => r.x === header);
			if (target) {
				row.push(target.y);
			}
		});
		csv.push(`${obj.id},${row.join(",")}`);
	});

	return csv.join("\n");
};

export {
	heatmapItemToggleTooltip,
	showHeatmapAxisPopover,
	showHeatmapLegendPopover,
	hideHeatmapPopover,
	convertHeatmapDataToCSV,
	toggleHeatmapLegendHoverClass,
};
